import { NextResponse } from 'next/server';

const INDEXNOW_KEY = 'ef26759c25ad4cf0b5a1b32b35a7dbcf';
const INDEXNOW_KEY_LOCATION = 'https://www.trayago.in/ef26759c25ad4cf0b5a1b32b35a7dbcf.txt';
const HOST = 'www.trayago.in';

export async function POST(request: Request) {
  try {
    const body = await request.json();
    const { urlList } = body;

    if (!urlList || !Array.isArray(urlList) || urlList.length === 0) {
      return NextResponse.json(
        { success: false, error: 'urlList must be a non-empty array of absolute URLs' },
        { status: 400 }
      );
    }

    // Validate that all URLs are absolute and target the canonical domain
    for (const url of urlList) {
      if (typeof url !== 'string' || !url.startsWith('https://www.trayago.in')) {
        return NextResponse.json(
          { success: false, error: `Invalid URL: "${url}". URLs must be absolute and target https://www.trayago.in` },
          { status: 400 }
        );
      }
    }

    // Prepare IndexNow payload
    const payload = {
      host: HOST,
      key: INDEXNOW_KEY,
      keyLocation: INDEXNOW_KEY_LOCATION,
      urlList: urlList,
    };

    console.log('[INDEXNOW] Submitting payload:', payload);

    // Call unified IndexNow endpoint
    const response = await fetch('https://api.indexnow.org/indexnow', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json; charset=utf-8',
      },
      body: JSON.stringify(payload),
    });

    if (response.status === 200 || response.status === 202) {
      return NextResponse.json({
        success: true,
        message: 'URLs submitted successfully to IndexNow',
        status: response.status,
      });
    } else {
      const text = await response.text();
      return NextResponse.json(
        {
          success: false,
          error: `IndexNow returned status ${response.status}`,
          details: text,
        },
        { status: response.status }
      );
    }
  } catch (error: any) {
    console.error('[INDEXNOW] Submission failed:', error);
    return NextResponse.json(
      { success: false, error: error.message || 'Internal Server Error' },
      { status: 500 }
    );
  }
}
